/* From Uiverse.io by Prince4fff - Tags: card */
.__UIV_SCOPE__ .card p {
  font-size: 17px;
  font-weight: 400;
  line-height: 20px;
  color: #666;
}

.__UIV_SCOPE__ .card p.small {
  font-size: 14px;
}

.__UIV_SCOPE__ .go-corner {
  display: flex;
  align-items: center;
  justify-content: center;
  position: absolute;
  width: 32px;
  height: 32px;
  overflow: hidden;
  top: 0;
  right: 0;
  background-color: #00838d;
  border-radius: 0 4px 0 32px;
}

.__UIV_SCOPE__ .go-arrow {
  margin-top: -4px;
  margin-right: -4px;
  color: white;
  font-family: courier, sans;
}

.__UIV_SCOPE__ .card1 {
  display: block;
  position: relative;
  max-width: 262px;
  background-color: #f2f8f9;
  border-radius: 4px;
  padding: 32px 24px;
  margin: 12px;
  text-decoration: none;
  z-index: 0;
  overflow: hidden;
}

.__UIV_SCOPE__ .card1:before {
  content: "";
  position: absolute;
  z-index: -1;
  top: -16px;
  right: -16px;
  background: #00838d;
  height: 32px;
  width: 32px;
  border-radius: 32px;
  transform: scale(1);
  transform-origin: 50% 50%;
  transition: transform 0.25s ease-out;
}

.__UIV_SCOPE__ .card1:hover:before {
  transform: scale(21);
}

.__UIV_SCOPE__ .card1:hover p {
  transition: all 0.3s ease-out;
  color: rgba(255, 255, 255, 0.8);
}

.__UIV_SCOPE__ .card1:hover h3 {
  transition: all 0.3s ease-out;
  color: #fff;
}

.__UIV_SCOPE__ .card2 {
  display: block;
  top: 0px;
  position: relative;
  max-width: 262px;
  background-color: #f2f8f9;
  border-radius: 4px;
  padding: 32px 24px;
  margin: 12px;
  text-decoration: none;
  z-index: 0;
  overflow: hidden;
  border: 1px solid #f2f8f9;
}

.__UIV_SCOPE__ .card2:hover {
  transition: all 0.2s ease-out;
  box-shadow: 0px 4px 8px rgba(38, 38, 38, 0.2);
  top: -4px;
  border: 1px solid #ccc;
  background-color: white;
}

.__UIV_SCOPE__ .card2:before {
  content: "";
  position: absolute;
  z-index: -1;
  top: -16px;
  right: -16px;
  background: #00838d;
  height: 32px;
  width: 32px;
  border-radius: 32px;
  transform: scale(2);
  transform-origin: 50% 50%;
  transition: transform 0.15s ease-out;
}

.__UIV_SCOPE__ .card2:hover:before {
  transform: scale(2.15);
}

.__UIV_SCOPE__ .card3 {
  display: block;
  top: 0px;
  position: relative;
  max-width: 262px;
  background-color: #f2f8f9;
  border-radius: 4px;
  padding: 32px 24px;
  margin: 12px;
  text-decoration: none;
  overflow: hidden;
  border: 1px solid #f2f8f9;
}

.__UIV_SCOPE__ .card3 .go-corner {
  opacity: 0.7;
}

.__UIV_SCOPE__ .card3:hover {
  border: 1px solid #00838d;
  box-shadow: 0px 0px 999px 999px rgba(255, 255, 255, 0.5);
  z-index: 500;
}

.__UIV_SCOPE__ .card3:hover p {
  color: #00838d;
}

.__UIV_SCOPE__ .card3:hover .go-corner {
  transition: opactiy 0.3s linear;
  opacity: 1;
}

.__UIV_SCOPE__ .card4 {
  display: block;
  top: 0px;
  position: relative;
  max-width: 262px;
  background-color: #fff;
  border-radius: 4px;
  padding: 32px 24px;
  margin: 12px;
  text-decoration: none;
  overflow: hidden;
  border: 1px solid #ccc;
}

.__UIV_SCOPE__ .card4 .go-corner {
  background-color: #00838d;
  height: 100%;
  width: 16px;
  padding-right: 9px;
  border-radius: 0;
  transform: skew(6deg);
  margin-right: -36px;
  align-items: start;
  background-image: linear-gradient(-45deg, #8f479a 1%, #dc2a74 100%);
}

.__UIV_SCOPE__ .card4 .go-arrow {
  transform: skew(-6deg);
  margin-left: -2px;
  margin-top: 9px;
  opacity: 0;
}

.__UIV_SCOPE__ .card4:hover {
  border: 1px solid #cd3d73;
}

.__UIV_SCOPE__ .card4 h3 {
  margin-top: 8px;
}

.__UIV_SCOPE__ .card4:hover .go-corner {
  margin-right: -12px;
}

.__UIV_SCOPE__ .card4:hover .go-arrow {
  opacity: 1;
}
